/**
 * Writes evm/client/abi.ts from Foundry's build output, so viem calls are
 * typed against the contracts as compiled. Run after `forge build`:
 *
 *   npm run evm:abi
 */
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const out = join(import.meta.dirname, "..", "out");
const abi = (file: string, name: string) => JSON.parse(readFileSync(join(out, file, `${name}.json`), "utf8")).abi;

const body = [
  "// Generated by evm/scripts/abi.ts from forge's build output. Don't edit.",
  `export const afterbellVaultAbi = ${JSON.stringify(abi("AfterbellVault.sol", "AfterbellVault"), null, 2)} as const;`,
  `export const afterbellPositionsAbi = ${JSON.stringify(abi("AfterbellPositions.sol", "AfterbellPositions"), null, 2)} as const;`,
  `export const testUsdAbi = ${JSON.stringify(abi("TestUSD.sol", "TestUSD"), null, 2)} as const;`,
  "",
].join("\n\n");
writeFileSync(join(import.meta.dirname, "..", "client", "abi.ts"), body);
console.log("wrote evm/client/abi.ts");
